mapper.select:
SELECT id, floor_plan_id, created_by, current_version_id, title, description, created_at FROM layouts
AND created_by = #{createdBy}
AND title LIKE CONCAT('%', #{query}, '%')
ORDER BY id DESC LIMIT #{offset}, #{size}

SELECT DISTINCT l.id, l.floor_plan_id, l.created_by, l.current_version_id, l.title, l.description, l.created_at FROM layouts l INNER JOIN layout_zones z ON z.layout_version_id = l.current_version_id AND z.assigned_user_id = #{userId}
WHERE l.title LIKE CONCAT('%', #{query}, '%')
ORDER BY l.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM layouts
AND created_by = #{createdBy}
AND title LIKE CONCAT('%', #{query}, '%')

