UPDATE fabrics
SET movement_policy = #{movementPolicy}
WHERE id = #{id} AND layout_version_id = #{layoutVersionId}

UPDATE layout_zones
SET default_exit_id = CASE WHEN default_exit_id IN

        #{exitId}

    THEN NULL ELSE default_exit_id END
WHERE layout_version_id = #{layoutVersionId}

UPDATE layouts
SET title = #{title},
    description = #{description}
WHERE id = #{id}

UPDATE layouts
SET current_version_id = #{currentVersionId}
WHERE id = #{id}

UPDATE layout_versions
SET optimistic_lock = #{nextLock}
WHERE id = #{id}
  AND optimistic_lock = #{expectedLock}
  AND status = '초안'

mapper.select:
SELECT lv.layout_id AS layoutId, COUNT(*) AS simulationCount FROM simulations s JOIN layout_versions lv ON s.layout_version_id = lv.id WHERE lv.layout_id IN
#{layoutId}
GROUP BY lv.layout_id
